insert into constraint_types(name, targets, explain) values
  ('عدم تزامن الحصص', 'معلّم', 'حصص المعلّم لا تقع في الخانة نفسها مع حصص معلّم آخر. القيمة: اسم المعلّم الآخر، وبين قوسين الصف إن خُصّ.'),
  ('عدد الحصص الأولى', 'معلّم', 'أدنى عدد أيام يبدأ فيها المعلّم بالحصّة المذكورة في الأسبوع. القيمة: «الحصّة: عدد الأيام».'),
  ('لا حصّتين أخيرتين متتاليتين', 'معلّم،مادّة', 'لا تجتمع السادسة والسابعة للمعلّم في يوم واحد (بهدف «مادّة»: كل من يدرّسها).'),
  ('لا سادسة بلا سابعة', 'معلّم', 'لا يأخذ المعلّم السادسة في يوم ليس فيه سابعته.'),
  ('حصّة مكرّرة محجوبة', 'معلّم', 'حصّتا المادّة نفسها للصف نفسه في يوم واحد لا تقعان في اليوم المذكور. القيمة: اليوم.'),
  ('لا حصّة للمادّة في صفّ', 'مادّة', 'حصص المادّة في الصف المذكور لا تقع في هذه الحصص. القيمة: «الصف: الحصص».'),
  ('يوم بلا حصص', 'معلّم،مادّة', 'يوم فارغ لكل معلّم (بهدف «مادّة»: لكل من يدرّسها) إن أمكن.')
