-- تحويل القيود إلى قالب ورقة «القيود» (مواصفة 2026-10-11، القسم ١١). يُشغَّل مرة واحدة بعد 20261011_constraints_template.sql.
-- يحذف القيود الـ108 القديمة ويكتب 104 قيداً بالقالب، و7 أنواع مقترحة. نسخة القديمة: constraints_before_2026-10-11.json.
begin;
on conflict (name) do nothing;
delete from constraints where id <= 111;
select setval(pg_get_serial_sequence('constraints', 'id'), (select max(id) from constraints));
-- الطلبات المنجزة الـ11 حُوّلت قيوداً من قبل، ولا مرفقات لها (تحقق 2026-10-11): تُحذف نهائياً (البند ٣).
delete from requests where done and coalesce(jsonb_array_length(files), 0) = 0 and file_path is null;
commit;
